value.customCss:
/* ================= 基础重置 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { 
    margin: 0 !important; 
    padding: 0 !important; 
    border: none !important; 
    display: block !important; 
    box-shadow: none !important; 
    white-space: pre-wrap !important; 
    outline: none !important; 
    background: transparent !important; 
    border-radius: 0 !important; 
}

/* ================= 根容器 ================= */
.xt-root {
    width: 100% !important;
    max-width: 400px !important;
    height: 650px !important;
    background-color: #ffffff !important;
    position: relative !important;
    margin: 0 auto !important;
    padding: 0 !important;
    overflow-y: auto !important;
    overflow-x: hidden !important;
    font-family: 'Lucida Grande', 'Lucida Sans Unicode', 'GNU Unifont', Verdana, Helvetica, sans-serif !important;
    color: #2a2a2a !important;
    border-radius: 0 !important; 
    -webkit-overflow-scrolling: touch !important;
}

.xt-root::-webkit-scrollbar { width: 4px !important; }
.xt-root::-webkit-scrollbar-track { background: transparent !important; }
.xt-root::-webkit-scrollbar-thumb { background: #ccc !important; border-radius: 0 !important; }

/* ================= 顶部 Header ================= */
/* Logo */
.xt-text:nth-of-type(1) {
    position: relative !important;
    padding: 15px 10px 10px 50px !important; 
    font-size: 22px !important;
    font-family: Georgia, serif !important;
    color: #990000 !important;
    background-color: #ffffff !important;
    font-weight: bold !important;
}
.xt-text:nth-of-type(1)::before {
    content: '' !important;
    position: absolute !important;
    left: 0px !important;
    top: 5px !important;
    width: 50px !important; 
    height: 50px !important;
    background-image: url('https://i.postimg.cc/prLTnDgD/IMG-8126.png') !important;
    background-size: contain !important;
    background-repeat: no-repeat !important;
    background-position: center !important;
}
.xt-text:nth-of-type(1)::after {
    display: none !important;
}

/* Log In */
.xt-text:nth-of-type(2) {
    position: absolute !important;
    top: 15px !important;
    right: 15px !important;
    font-size: 14px !important;
    color: #900 !important;
    z-index: 10 !important;
    text-decoration: underline !important;
}

/* ================= 红色导航栏 ================= */
.xt-text:nth-of-type(3) {
    position: relative !important;
    width: 100% !important; 
    left: 0 !important;
    margin: 0 !important;
    background-color: #990000 !important;
    background-image: linear-gradient(rgba(0,0,0,0.1) 1px, transparent 1px), linear-gradient(90deg, rgba(0,0,0,0.1) 1px, transparent 1px) !important;
    background-size: 3px 3px !important;
    color: #ffffff !important;
    padding: 10px 15px !important;
    font-size: 14px !important;
    word-spacing: 15px !important;
    border-top: 1px solid #660000 !important;
    border-bottom: 1px solid #660000 !important;
    border-radius: 0 !important; 
}

.xt-text:nth-of-type(3)::after {
    content: '' !important;
    display: block !important;
    width: 50% !important;
    height: 22px !important;
    background-color: #ffffff !important;
    border-radius: 0 !important; 
    margin-top: 10px !important;
    margin-left: auto !important;
    margin-right: 60px !important;
}

/* Search 按钮 */
.xt-text:nth-of-type(4) {
    position: absolute !important;
    top: 101px !important; 
    right: 15px !important;
    background-color: #e3e3e3 !important;
    border: 1px solid #ccc !important;
    border-radius: 0 !important; 
    padding: 2px 6px !important;
    font-size: 12px !important;
    color: #333 !important;
    z-index: 10 !important;
}

/* ================= 操作按钮区 ================= */
.xt-text:nth-of-type(5),
.xt-text:nth-of-type(6),
.xt-text:nth-of-type(7) {
    display: inline-block !important;
    background-color: #f5f5f5 !important;
    border: 1px solid #ccc !important;
    border-radius: 0 !important; 
    padding: 4px 10px !important;
    font-size: 13px !important;
    color: #333 !important;
    margin-top: 15px !important;
    margin-bottom: 15px !important;
}
.xt-text:nth-of-type(5) { margin-left: 15px !important; }
