value.customCss:
/* ================= 引入自定义字体 ================= */
@font-face {
    font-family: 'ContentCustomFont';
    src: url('https://nos.netease.com/ysf/d295793f0312c7821099f842f62b907b.ttf') format('truetype');
    font-weight: normal;
    font-style: normal;
    font-display: swap;
}

/* ================= 基础重置 ================= */
.xt-root * { box-sizing: border-box !important; }
.xt-header, .xt-badge, .xt-grid, .xt-section, .xt-toggle, .xt-action-1, .xt-action-2 { display: none !important; }
.xt-text { margin: 0 !important; padding: 0 !important; border: none !important; display: block !important; box-shadow: none !important; white-space: pre-wrap !important; outline: none !important; background: transparent !important; }
.xt-root::-webkit-scrollbar, .xt-text::-webkit-scrollbar { display: none !important; width: 0 !important; }

/* ================= 全局字体：打字机风格 ================= */
.xt-text {
    font-family: 'Courier New', Courier, monospace, 'STKaiti', serif !important;
    color: #3b4a40 !important; /* 字体颜色微调为深绿灰 */
}

/* ================= 纸张主体 (直角，低饱和淡绿渐变) ================= */
.xt-root {
    width: 340px !important;
    height: 500px !important;
    /* 从纯白渐变到主人指定的淡绿色 */
    background: linear-gradient(135deg, #ffffff 0%, #f6fcf8 100%) !important; 
    position: relative !important;
    margin: 20px auto 100px auto !important; 
    display: block !important;
    overflow: visible !important; 
    border-radius: 2px !important; 
    box-shadow: 
        0 8px 25px rgba(17, 70, 42, 0.06), /* 阴影带一点绿调 */
        inset 0 0 30px rgba(17, 70, 42, 0.02) !important;
}

/* 纸张微弱纹理 */
.xt-root::before {
    content: '' !important;
    position: absolute !important;
    top: 0 !important; left: 0 !important;
    width: 100% !important; height: 100% !important;
    background-image: url('data:image/svg+xml;base64,PHN2ZyB4bWxucz0iaHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmciIHdpZHRoPSI0IiBoZWlnaHQ9IjQiPgo8cmVjdCB3aWR0aD0iNCIgaGVpZ2h0PSI0IiBmaWxsPSIjZmZmIiBmaWxsLW9wYWNpdHk9IjAiLz4KPHBhdGggZD0iTTAgMEg0VjRIMHoiIGZpbGw9IiMwMDAiIGZpbGwtb3BhY2l0eT0iMC4wMSIvPgo8L3N2Zz4=') !important;
    pointer-events: none !important;
    z-index: 1 !important;
}

/* ================= 纸张内文字排版 ================= */
/* 顶部左侧文字 */
.xt-text:nth-of-type(1) {
    position: absolute !important;
    top: 35px !important; left: 25px !important;
    font-size: 11px !important;
    font-weight: 600 !important;
    letter-spacing: 1.5px !important;
    color: #7a9e8b !important; /* 偏绿的灰色 */
    z-index: 2 !important;
}

/* 顶部右侧文字 */
.xt-text:nth-of-type(2) {
    position: absolute !important;
    top: 35px !important; right: 25px !important;
    font-size: 11px !important;
    font-weight: 600 !important;
    letter-spacing: 1.5px !important;
    color: #7a9e8b !important;
    z-index: 2 !important;
}

/* 顶部实线 */
.xt-text:nth-of-type(3) {
    position: absolute !important;
    top: 55px !important; left: 25px !important;
    width: 290px !important; height: 1px !important;
    border-top: 1px solid #5c8a73 !important; /* 偏绿的深色 */
    color: transparent !important;
    z-index: 2 !important;
}

/* 正文区域 (支持上下滑动，使用专属字体) */
.xt-text:nth-of-type(4) {
    position: absolute !important;
    top: 85px !important; left: 25px !important;
    width: 290px !important; height: 300px !important;
    font-family: 'ContentCustomFont', 'Courier New', Courier, monospace, 'STKaiti', serif !important; 
    font-size: 16px !important; 
    line-height: 1.9 !important;
    overflow-y: auto !important; 
    z-index: 10 !important; 
    pointer-events: auto !important;
    padding-right: 8px !important; 
    padding-bottom: 20px !important; 
    -webkit-transform: translateZ(0) !important;
    transform: translateZ(0) !important;
    will-change: transform, scroll-position !important;
    -webkit-backface-visibility: hidden !important;
    backface-visibility: hidden !important;
}

/* 为正文区域定制精致的细滚动条 */
.xt-text:nth-of-type(4)::-webkit-scrollbar {
    display: block !important;
    width: 3px !important;
}
.xt-text:nth-of-type(4)::-webkit-scrollbar-track {
    background: transparent !important;
}
.xt-text:nth-of-type(4)::-webkit-scrollbar-thumb {
    background: rgba(44, 80, 62, 0.15) !important; /* 滚动条带绿调 */
    border-radius: 2px !important;
}
.xt-text:nth-of-type(4)::-webkit-scrollbar-thumb:hover {
    background: rgba(44, 80, 62, 0.3) !important;
}

/* 底部标题 */
.xt-text:nth-of-type(5) {
    position: absolute !important;
    bottom: 55px !important; left: 25px !important;
    font-size: 11px !important;
    font-weight: 600 !important;
    letter-spacing: 1.5px !important;
    color: #7a9e8b !important;
    z-index: 2 !important;
}

/* 底部虚线 */
.xt-text:nth-of-type(6) {
    position: absolute !important;
    bottom: 45px !important; left: 25px !important;
    width: 290px !important; height: 1px !important;
    border-top: 1px dotted #7a9e8b !important;
    color: transparent !important;
    z-index: 2 !important;
}

/* 底部描述 */
.xt-text:nth-of-type(7) {
    position: absolute !important;
    bottom: 25px !important; left: 25px !important;
    font-size: 11px !important;
    letter-spacing: 1px !important;
    color: #9ab8a6 !important;
    z-index: 2 !important;
}

/* ================= 精致浅灰打字机绘制 (纯CSS) ================= */
/* 1. 打字机底座 (偏冷绿的银灰) */
.xt-text:nth-of-type(8) {
    position: absolute !important;
    bottom: -80px !important; left: -10px !important; 
    width: 360px !important; height: 100px !important;
    background: linear-gradient(135deg, #e6f8ef 0%, #c4e6d4 100%) !important; 
    border-radius: 8px 8px 15px 15px !important;
    box-shadow: 
        inset 0 2px 4px rgba(255,255,255,0.9), 
        inset 0 -5px 10px rgba(17, 70, 42, 0.08), 
        0 15px 25px rgba(17, 70, 42, 0.12), 
        0 3px 6px rgba(17, 70, 42, 0.06) !important;
    z-index: 10 !important;
    color: transparent !important;
    pointer-events: none !important;
}
.xt-text:nth-of-type(8)::before {
    content: '' !important;
