}

/* 2. 打字机内部滚筒槽 & 精致银色压纸杆 (深绿灰) */
.xt-text:nth-of-type(9) {
    position: absolute !important;
    bottom: -20px !important; left: 10px !important;
    width: 320px !important; height: 45px !important; 
    background: linear-gradient(to bottom, #355240, #456652) !important; 
    border-radius: 3px !important;
    box-shadow: 
        inset 0 8px 12px rgba(0,0,0,0.4),
