}
.xt-text:nth-of-type(10)::after {
    content: '' !important;
    position: absolute !important;
    top: 15px !important; right: -15px !important;
    width: 18px !important; height: 26px !important;
    background: linear-gradient(to left, #b8d9c6, #e6f8ef, #b8d9c6) !important;
    border-radius: 0 3px 3px 0 !important;
