value.customCss:
@import url('https://fonts.googleapis.com/css2?family=SF+Pro+Display:wght@400;500;600;700&display=swap');

.xt-root {
    /* 从上往下渐变：顶部接近透明，向下延伸为清透的浅蓝色毛玻璃 */
    background: linear-gradient(to bottom, rgba(240, 247, 255, 0.15) 0%, rgba(170, 215, 250, 0.6) 100%) !important;
    backdrop-filter: blur(20px) saturate(180%) !important;
    -webkit-backdrop-filter: blur(20px) saturate(180%) !important;

    --xt-text: #0f172a;
    --xt-text-sub: #334155;
    --xt-text-muted: #64748b;
    --xt-border: rgba(255, 255, 255, 0.45);
    --xt-btn-bg: rgba(255, 255, 255, 0.5);
    --xt-expand-bg: rgba(255, 255, 255, 0.35);

    color: var(--xt-text);
    padding: 16px;
    border-radius: 18px;
    border: 1px solid var(--xt-border);
    box-shadow: 0 16px 32px rgba(31, 38, 135, 0.08), inset 0 1px 0 rgba(255, 255, 255, 0.7);
}

/* 顶部标题栏 */
.xt-header {
    position: relative !important;
    height: 48px !important;
    margin-top: 8px !important;
    margin-bottom: 12px !important;
    padding: 0 !important;
    display: block !important;
}

/* 1. 【最左】資料庫标题 */
.xt-name {
    position: absolute !important;
    left: 0 !important;
    top: 6px !important;
    font-size: 0 !important;
    margin: 0 !important;
}
.xt-name::after {
    content: "資料庫" !important;
    font-size: 26px !important;
    font-weight: 700 !important;
    color: var(--xt-text) !important;
    letter-spacing: -0.5px !important;
    display: block !important;
    line-height: 36px !important;
}

/* 2. 【靠右】+ ≡ 胶囊按钮（半透明亮色磨砂质感） */
.xt-header::after {
    content: "+ ≡" !important;
    position: absolute !important;
    right: 48px !important;
    top: 6px !important;
    height: 36px !important;
    box-sizing: border-box !important;
    font-size: 13px !important;
    font-weight: 500 !important;
    color: var(--xt-text) !important;
    background: var(--xt-btn-bg) !important;
    backdrop-filter: blur(12px);
    -webkit-backdrop-filter: blur(12px);
    border: 1px solid rgba(255, 255, 255, 0.6);
    padding: 0 14px !important;
    border-radius: 20px !important;
    letter-spacing: 1px !important;
    display: flex !important;
    align-items: center !important;
    justify-content: center !important;
}

/* 3. 【最右】角色头像 */
.xt-avatar {
    position: absolute !important;
    right: 0 !important;
    top: 6px !important;
    width: 36px !important;
    height: 36px !important;
    border-radius: 50% !important;
    border: 1.5px solid rgba(255, 255, 255, 0.8) !important;
    object-fit: cover !important;
    margin: 0 !important;
    box-shadow: 0 4px 10px rgba(0,0,0,0.08);
}

/* 分割线 */
.xt-divider {
    height: 1px;
    background: var(--xt-border);
    border: none;
    margin: 4px 0;
}

/* 折叠菜单项样式 */
.xt-collapse {
    border: none;
    border-bottom: 1px solid var(--xt-border);
    background: transparent;
    border-radius: 0;
    margin: 0;
}
.xt-collapse-header {
    background: transparent;
    color: var(--xt-text);
    font-size: 15px;
    font-weight: 400;
    padding: 14px 4px;
}
.xt-collapse-arrow {
    color: var(--xt-text-muted);
    font-size: 12px;
    font-weight: 300;
}

/* 未展开时高度与边距清零 */
.xt-collapse-body {
    max-height: 0;
    padding: 0 !important;
    margin: 0 !important;
    background: transparent !important;
    border: none !important;
    overflow: hidden;
    transition: max-height 0.3s ease, padding 0.3s ease;
}

/* 点击展开时显示具体内容与清透毛玻璃背景 */
#xt-t1:checked ~ .xt-content .xt-collapse-1 .xt-collapse-body,
#xt-t2:checked ~ .xt-content .xt-collapse-2 .xt-collapse-body,
#xt-t3:checked ~ .xt-content .xt-collapse-3 .xt-collapse-body,
#xt-t4:checked ~ .xt-content .xt-collapse-4 .xt-collapse-body {
    max-height: 200px;
    padding: 10px 12px !important;
    background: var(--xt-expand-bg);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border: 1px solid rgba(255, 255, 255, 0.4);
    border-radius: 8px;
    margin-top: 4px !important;
    margin-bottom: 10px !important;
    color: var(--xt-text-sub);
    font-size: 13px;
    line-height: 1.6;
    white-space: pre-line !important;
}

