.xt-text-f1Text, .xt-text-f2Text, .xt-text-f3Text { background: #494745 !important; border-radius: 0 0 10px 10px !important; padding: 0 16px 16px 16px !important; color: #e6e6e6; font-size: 15px; line-height: 1.6; text-align: justify; margin-top: 0 !important; margin-bottom: 12px !important; }
.xt-text-f1Text::after { content: "赞同 42 \A0\A0\A0\A0 · \A0\A0\A0\A0 回复 12"; display: block; margin-top: 14px; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 12px; color: #8c8a88; font-size: 12px; text-align: center; }
.xt-text-f2Text::after { content: "赞同 128 \A0\A0\A0\A0 · \A0\A0\A0\A0 回复 35"; display: block; margin-top: 14px; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 12px; color: #8c8a88; font-size: 12px; text-align: center; }
.xt-text-f3Text::after { content: "赞同 854 \A0\A0\A0\A0 · \A0\A0\A0\A0 回复 99"; display: block; margin-top: 14px; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 12px; color: #8c8a88; font-size: 12px; text-align: center; }

/* 水印级暗藏按钮 */
.xt-action-1 { display: block; text-align: center; font-size: 12px; color: #bbbbbb; margin: 0 auto 0 auto; letter-spacing: 2px; cursor: pointer; background: transparent !important; border: none !important; }
.xt-action-1::after { content: "微信读书"; }

.xt-text-p2Title, .xt-text-chatTitle, .xt-bubbles, .xt-card,
.xt-text-innerNum, .xt-text-innerMonologue, .xt-text-innerSign,
.xt-text-qaTitle, .xt-text-qaQ, .xt-text-qaA,
.xt-text-surfaceWords, .xt-text-trueWords,
.xt-text-hlQuote, .xt-text-hlNum,
.xt-text-f1Name, .xt-text-f1Text,
.xt-text-f2Name, .xt-text-f2Text,
.xt-text-f3Name, .xt-text-f3Text { display: none !important; }

@keyframes pageFadeIn { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: translateY(0); } }

#xt-t1:checked ~ .xt-content .xt-text-day,
#xt-t1:checked ~ .xt-content .xt-text-monthYear,
#xt-t1:checked ~ .xt-content .xt-text-weekday,
#xt-t1:checked ~ .xt-content .xt-divider,
#xt-t1:checked ~ .xt-content .xt-text-quote,
#xt-t1:checked ~ .xt-content .xt-text-bookName,
#xt-t1:checked ~ .xt-content .xt-text-author { display: none !important; }

#xt-t1:checked ~ .xt-content .xt-text-p2Title,
#xt-t1:checked ~ .xt-content .xt-text-chatTitle,
#xt-t1:checked ~ .xt-content .xt-card,
#xt-t1:checked ~ .xt-content .xt-text-innerNum,
#xt-t1:checked ~ .xt-content .xt-text-innerMonologue,
#xt-t1:checked ~ .xt-content .xt-text-innerSign,
#xt-t1:checked ~ .xt-content .xt-text-qaTitle,
#xt-t1:checked ~ .xt-content .xt-text-qaQ,
#xt-t1:checked ~ .xt-content .xt-text-qaA,
#xt-t1:checked ~ .xt-content .xt-text-surfaceWords,
#xt-t1:checked ~ .xt-content .xt-text-trueWords,
#xt-t1:checked ~ .xt-content .xt-text-hlQuote,
#xt-t1:checked ~ .xt-content .xt-text-hlNum,
#xt-t1:checked ~ .xt-content .xt-text-f1Text,
#xt-t1:checked ~ .xt-content .xt-text-f2Text,
#xt-t1:checked ~ .xt-content .xt-text-f3Text { display: block !important; animation: pageFadeIn 0.5s ease forwards; }

#xt-t1:checked ~ .xt-content .xt-text-f1Name,
#xt-t1:checked ~ .xt-content .xt-text-f2Name,
#xt-t1:checked ~ .xt-content .xt-text-f3Name { display: flex !important; animation: pageFadeIn 0.5s ease forwards; }
#xt-t1:checked ~ .xt-content .xt-bubbles { display: flex !important; flex-direction: column; animation: pageFadeIn 0.5s ease forwards; }
#xt-t1:checked ~ .xt-content .xt-action-1::after { content: "返回日历"; }

value.layout:
# --- 第一页：日历与金句 ---
@text day
@text monthYear
@text weekday
@divider
@text quote
@text bookName
@text author

# --- 第二页：社区与思绪 ---
@text p2Title
@card
  @text innerNum
  @text innerMonologue
  @text innerSign
@endcard

@text chatTitle
@bubbles
  chat1:left
  chat2:right
  chat3:left
  chat4:right

@card
  @text qaTitle
  @text qaQ
  @text qaA
@endcard

# 模块4：表面与真心
@text surfaceWords
@text trueWords

# 模块5：暗黑模式划线评论区
@spacer 10
@text hlQuote
@text hlNum
@text f1Name
@text f1Text
@text f2Name
@text f2Text
@text f3Name
@text f3Text

@spacer 10
# 翻页按钮（伪装成微信读书水印）
@toggle 1
